package com.micon.backend.voice.application;
import com.micon.backend.common.exception.*; import com.micon.backend.voice.api.*; import com.micon.backend.voice.domain.*; import java.time.LocalDateTime; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.multipart.MultipartFile; import org.springframework.jdbc.core.JdbcTemplate;
@Service
public class TimbreAnalysisLifecycleService {
 private final VoiceAnalysisSessionRepository sessions; private final VoiceAnalysisJobRepository parents; private final VoiceAnalysisComponentJobRepository components; private final VoiceRecordingRepository recordings; private final VoiceRecordingContextRepository contexts; private final VoiceRecordingSegmentRepository segments; private final JdbcTemplate jdbc;
 public TimbreAnalysisLifecycleService(VoiceAnalysisSessionRepository s,VoiceAnalysisJobRepository p,VoiceAnalysisComponentJobRepository c,VoiceRecordingRepository r,VoiceRecordingContextRepository x,VoiceRecordingSegmentRepository g,JdbcTemplate j){sessions=s;parents=p;components=c;recordings=r;contexts=x;segments=g;jdbc=j;}
 @Transactional public Prepared create(long uid,long sid,MultipartFile file,VoiceAnalysisUploadRequest req){
  VoiceAnalysisJob old=parents.findByRequestId(req.requestId()).orElse(null); if(old!=null){if(!old.getSession().getId().equals(sid)||!old.getSession().getUser().getId().equals(uid))throw new BusinessException(ErrorCode.INVALID_REQUEST);return new Prepared(old.getStatus(),VoiceAnalysisJobResponse.from(old));}
  VoiceAnalysisSession s=sessions.findByIdAndUserId(sid,uid).orElseThrow(()->new BusinessException(ErrorCode.VOICE_ANALYSIS_NOT_FOUND)); if(s.isExpired())throw new BusinessException(ErrorCode.INVALID_VOICE_ANALYSIS_STATE); Integer count=jdbc.queryForObject("SELECT COUNT(*) FROM song WHERE song_id=?",Integer.class,req.songId());if(count==null||count==0)throw new BusinessException(ErrorCode.SONG_NOT_FOUND);
  int attempt=parents.findFirstBySessionIdOrderByAttemptNoDesc(sid).map(x->x.getAttemptNo()+1).orElse(1);
  VoiceRecording r=recordings.saveAndFlush(VoiceRecording.metadataOnly(s.getUser(),(short)attempt,file.getContentType(),file.getSize(),req.durationMs(),req.sampleRate()));
  contexts.save(new VoiceRecordingContext(r,s,req.songId(),req.startPositionType(),req.selectedStartMs(),req.actualStartMs(),req.durationMs(),req.instrumentalVersion(),req.lyricsVersion(),req.requestId()));short seq=1;if(req.segments()!=null)for(VoiceAnalysisUploadRequest.Segment q:req.segments())segments.save(new VoiceRecordingSegment(r,seq++,q.recordingStartMs(),q.recordingEndMs(),q.songStartMs(),q.songEndMs()));
  VoiceAnalysisJob p=parents.saveAndFlush(new VoiceAnalysisJob(s,r,req.requestId(),attempt)); components.save(new VoiceAnalysisComponentJob(p,"ECAPA"));components.save(new VoiceAnalysisComponentJob(p,"SINGER_BYOL"));s.beginTimbreAnalysis();return new Prepared("PENDING",VoiceAnalysisJobResponse.from(p));}
 @Transactional public VoiceAnalysisJobResponse queued(long uid,long id,String ai){VoiceAnalysisJob p=owned(uid,id);p.queued(ai);p.getSession().acceptTimbreAnalysis();return VoiceAnalysisJobResponse.from(p);}
 @Transactional public void unknown(long uid,long id,String reason){owned(uid,id).dispatchUnknown(reason);}
 @Transactional(readOnly=true) public VoiceAnalysisJobResponse latest(long uid,long sid){VoiceAnalysisJob p=parents.findFirstBySessionIdOrderByAttemptNoDesc(sid).filter(x->x.getSession().getUser().getId().equals(uid)).orElseThrow(()->new BusinessException(ErrorCode.VOICE_ANALYSIS_NOT_FOUND));return VoiceAnalysisJobResponse.from(p);}
 @Transactional public DirectVoiceAnalysisLifecycleService.CancelResult cancel(long uid,long sid,long id){VoiceAnalysisJob p=owned(uid,id);if(!p.getSession().getId().equals(sid))throw new BusinessException(ErrorCode.VOICE_ANALYSIS_NOT_FOUND);p.cancel(LocalDateTime.now());components.findByAnalysisJobId(id).forEach(x->x.cancel(LocalDateTime.now()));p.getSession().cancelTimbreAnalysis(LocalDateTime.now());return new DirectVoiceAnalysisLifecycleService.CancelResult(VoiceAnalysisJobResponse.from(p),p.getAiJobId());}
 private VoiceAnalysisJob owned(long uid,long id){return parents.findOwnedForUpdate(id,uid).orElseThrow(()->new BusinessException(ErrorCode.VOICE_ANALYSIS_NOT_FOUND));}
 public record Prepared(String status,VoiceAnalysisJobResponse response){}
}
